from solution import f
import math
import pytest
from hypothesis import given, strategies as st


def reference(n):
    out = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            out.append(math.factorial(i))
        else:
            out.append(i * (i + 1) // 2)
    return out


def test_example_f5_equals_spec():
    assert f(5) == [1, 2, 6, 24, 15]


def test_boundary_n0_is_empty():
    assert f(0) == []


def test_boundary_n1_is_singleton():
    assert f(1) == [1]


def test_boundary_n2_prefix():
    assert f(2) == [1, 2]


@given(st.integers(min_value=0, max_value=30))
def test_length_matches_n(n):
    assert isinstance(f(n), list)
    assert len(f(n)) == n


@given(st.integers(min_value=0, max_value=30))
def test_full_match_reference_model(n):
    assert f(n) == reference(n)


@given(st.integers(min_value=0, max_value=30))
def test_odd_positions_are_triangular_numbers(n):
    res = f(n)
    for i in range(1, n + 1):
        if i % 2 == 1:
            assert res[i - 1] == i * (i + 1) // 2 == sum(range(1, i + 1))


@given(st.integers(min_value=0, max_value=30))
def test_even_positions_are_factorials(n):
    res = f(n)
    for i in range(1, n + 1):
        if i % 2 == 0:
            assert res[i - 1] == math.factorial(i) == math.prod(range(1, i + 1))


@given(st.integers(min_value=0, max_value=30))
def test_elements_are_positive_ints(n):
    res = f(n)
    for v in res:
        assert type(v) == int
        assert v >= 1


@given(st.integers(min_value=0, max_value=30))
def test_prefix_consistency_truncation(n):
    full = f(n)
    for k in range(0, n + 1):
        assert f(k) == full[:k]


@given(st.integers(min_value=0, max_value=30))
def test_parity_alternation_formula(n):
    res = f(n)
    for i in range(1, n + 1):
        if i % 2 == 1:
            assert res[i - 1] == i * (i + 1) // 2
        else:
            assert res[i - 1] == math.factorial(i)
        # cross-check wrong formula must not hold except tiny coincidences
        if i > 2:
            if i % 2 == 1:
                assert res[i - 1] != math.factorial(i)
            else:
                assert res[i - 1] != i * (i + 1) // 2


def test_deterministic_repeated_calls_give_equal_new_lists():
    for n in [0, 1, 2, 5, 10]:
        a = f(n)
        b = f(n)
        assert a == b
        assert a is not b
